    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 12-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the bilateral. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["MRI of the hips", "CT scan of the pelvis", "Ultrasound of the hips", "AP radiograph of the pelvis", "Bone scan"]'::jsonb, 2, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'Patient #54827: A 6-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Transient synovitis", "Juvenile idiopathic arthritis", "Legg-Calv\u00e9-Perthes disease", "Slipped capital femoral epiphysis", "Septic arthritis"]'::jsonb, 0, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'Patient #35172: A 7-month-old infant is referred to orthopedics for asymmetric gluteal folds and a leg length discrepancy. Which imaging modality is considered the gold standard to evaluate for Developmental Dysplasia of the Hip (DDH) at this specific age?', '["CT scan", "MRI of the pelvis", "Ultrasound of the hips", "Bone scan", "AP radiograph of the pelvis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 9-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Adductus", "Cavus", "Varus", "Supination"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 13-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the left. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["CT scan of the pelvis", "Ultrasound of the hips", "MRI of the hips", "AP radiograph of the pelvis", "Bone scan"]'::jsonb, 1, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 13-year-old soccer player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Intra-articular corticosteroid injection", "Surgical excision of the ossicle", "Immobilization in a long leg cast for 6 weeks", "Strict non-weight bearing with crutches", "Activity modification, ice, NSAIDs, and reassurance"]'::jsonb, 4, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 10-year-old obese male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Pavlik harness", "Physical therapy and weight loss", "Open reduction and internal fixation", "Immediate non-weight bearing and in situ percutaneous pinning", "Closed reduction and spica casting"]'::jsonb, 3, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'Patient #45742: An 12-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Nonunion", "Avascular necrosis of the femoral head", "Chondrolysis", "Heterotopic ossification", "Infection"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 10-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the left. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["CT scan of the pelvis", "Bone scan", "AP radiograph of the pelvis", "MRI of the hips", "Ultrasound of the hips"]'::jsonb, 4, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'Patient #40407: An 13-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Infection", "Nonunion", "Heterotopic ossification", "Chondrolysis", "Avascular necrosis of the femoral head"]'::jsonb, 3, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 3-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.5°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["< 10% (Very low probability)", "About 50%", "Exactly 0%", "> 90% (Very high probability)", "About 25%"]'::jsonb, 3, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'A 16-day-old infant is brought to the clinic for unilateral right clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Supination", "Varus", "Adductus", "Cavus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 9-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the bilateral. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["AP radiograph of the pelvis", "CT scan of the pelvis", "MRI of the hips", "Bone scan", "Ultrasound of the hips"]'::jsonb, 4, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 5-year-old falls from a swing and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Axillary nerve", "Musculocutaneous nerve", "Radial nerve", "Ulnar nerve", "Anterior interosseous nerve (AIN)"]'::jsonb, 4, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 11-year-old soccer player presents with posterior heel pain. The pain worsens after running and improves with rest. Examination reveals tenderness upon medial-lateral compression of the calcaneal tuberosity (positive ''squeeze test''). There is tightness of the Achilles tendon. What is the most likely diagnosis?', '["Calcaneal apophysitis (Sever disease)", "Plantar fasciitis", "Achilles tendon rupture", "Calcaneal stress fracture", "Tarsal coalition"]'::jsonb, 0, 'Sever disease is a traction apophysitis of the calcaneus where the Achilles tendon inserts. It is a common cause of heel pain in athletic children aged 8-12. The classic exam finding is pain with medial/lateral compression of the heel. Treatment includes heel cups, calf stretching, and NSAIDs.'),
    (v_topic_id, 'A 6-year-old boy presents with a painless limp that has worsened over several weeks. He occasionally complains of vague right knee and thigh pain. He is afebrile and has limited internal rotation and abduction of the right hip. Radiographs show increased density and a subchondral crescent sign in the femoral head. What is the most likely diagnosis?', '["Developmental dysplasia of the hip", "Septic arthritis", "Slipped capital femoral epiphysis", "Legg-Calv\u00e9-Perthes disease", "Transient synovitis"]'::jsonb, 3, 'Legg-Calvé-Perthes disease is idiopathic avascular necrosis of the femoral head, classically seen in boys aged 4-8. It often presents insidiously with a painless limp or referred pain to the thigh/knee. Radiographs progress from sclerosis to fragmentation and reossification. The crescent sign represents a subchondral fracture.'),
    (v_topic_id, 'A 21-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Supination", "Cavus", "Varus", "Equinus", "Adductus"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 7-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Supination", "Adductus", "Varus", "Cavus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'Patient #15137: A 4-year-old child, who is at the 95th percentile for weight, presents with progressively worsening bowing of the left leg (genu varum). Radiographs show a prominent ''beak'' at the medial metaphysis of the proximal tibia. What is the diagnosis?', '["Infantile Blount disease", "Rickets", "Physiologic genu varum", "Achondroplasia", "Osgood-Schlatter disease"]'::jsonb, 0, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
